def review_changes(changes,approved):
    if not isinstance(approved,set):raise ValueError('explicit approved logical IDs required')
    seen=set();risks=[]
    for row in changes:
        ident=row['LogicalResourceId'];action=row['Action']
        if not isinstance(ident,str) or not ident or ident in seen or action not in ('Add','Modify','Remove'):raise ValueError('supported unique change projection required')
        seen.add(ident);risk=None
        if action=='Remove':risk='remove'
        elif action=='Modify':
            replacement=row.get('Replacement')
            if replacement not in ('True','False','Conditional'):raise ValueError('explicit replacement decision required')
            if replacement in ('True','Conditional'):risk='replace' if replacement=='True' else 'conditional_replace'
        if risk:risks.append(dict(logical_id=ident,risk=risk,approved=ident in approved))
    if not approved<=seen:raise ValueError('approval contains unknown logical ID')
    return dict(allowed=all(row['approved'] for row in risks),risks=sorted(risks,key=lambda row:row['logical_id']))
