import copy,re
from decimal import Decimal,localcontext
def decompose(previous,current):
    fields=('account','region','sku','unit','currency')
    def index(rows):
        found={}
        for row in rows:
            key=tuple(row[k] for k in fields)
            if any(not isinstance(v,str) or not v for v in key) or key in found:raise ValueError('unique billing identity required')
            for field in ('quantity','rate'):
                if not isinstance(row[field],str) or not re.fullmatch(r'(0|[1-9][0-9]{0,11})(\.[0-9]{1,6})?',row[field]):raise ValueError('bounded nonnegative decimal strings required')
            if not isinstance(row['tags'],dict):raise ValueError('explicit tags required')
            found[key]=row
        return found
    before=index(previous);after=index(current)
    if before.keys()!=after.keys():raise ValueError('unmatched SKU/unit/currency cannot be silently compared')
    result=[]
    with localcontext() as ctx:
        ctx.prec=64
        for key in sorted(before):
            old,new=before[key],after[key];q0,p0,q1,p1=[Decimal(v) for v in (old['quantity'],old['rate'],new['quantity'],new['rate'])]
            values=dict(old_cost=q0*p0,new_cost=q1*p1,price_effect=q0*(p1-p0),usage_effect=(q1-q0)*p1)
            result.append(dict(identity=dict(zip(fields,key)),**{k:format(v,'f') for k,v in values.items()},tags_changed=old['tags']!=new['tags'],old_tags=copy.deepcopy(old['tags']),new_tags=copy.deepcopy(new['tags'])))
    return result
